candidates.suggested_fix:
return elem.reduce(
  function (newElems, el) {
    var res = this._makeDomArray(el, clone);
    if (Array.isArray(res)) {
      newElems.push.apply(newElems, res);
    } else {
      newElems.push(res);
    }
    return newElems;
  }.bind(this),
  []
);

candidates.body:
**Performance (medium)**: The use of .concat inside .reduce leads to quadratic time complexity (O(N^2)) since a new array is created and copied on every iteration.

> `return newElems.concat(this._makeDomArray(el, clone));`

**Suggested fix:** return elem.reduce(
  function (newElems, el) {
    var res = this._makeDomArray(el, clone);
    if (Array.isArray(res)) {
      newElems.push.apply(newElems, res);
    } else {
      newElems.push(res);
    }
    return newElems;
  }.bind(this),
  []
);

candidates.suggested_fix:
return elem.children.filter(isTag).reduce(function (acc, child) {
  acc.push(child);
  return acc;
}, newElems);

candidates.body:
**Performance (medium)**: Repeatedly calling .concat within .reduce causes quadratic performance bottlenecks for large lists of DOM elements.

> `return newElems.concat(elem.children.filter(isTag));`

**Suggested fix:** return elem.children.filter(isTag).reduce(function (acc, child) {
  acc.push(child);
  return acc;
}, newElems);

